import sys, json, os, subprocess, time, logging

class AgentIntrospectionDebugger:
    def __init__(self, rule_path='rules.json', report_url=None):
        self.rules = json.load(open(rule_path))
        self.report_url = report_url
        self.logger = logging.getLogger('agent_debug')
        sys.excepthook = self.global_exception_handler

    def global_exception_handler(self, exc_type, exc_val, exc_tb):
        err_msg = f'{exc_type.__name__}: {exc_val}'
        root_cause = self.analyze_root_cause(err_msg)
        if root_cause.get('auto_fix'):
            self.apply_fix(root_cause)
        else:
            self.notify_human(err_msg, root_cause)

    def analyze_root_cause(self, error):
        for rule in self.rules:
            if rule['pattern'] in error:
                return rule
        return {'auto_fix': False, 'msg': 'Unknown error'}

    def apply_fix(self, fix):
        if fix['action'] == 'create_file':
            os.makedirs(os.path.dirname(fix['path']), exist_ok=True)
            with open(fix['path'], 'w') as f:
                f.write(fix.get('content', ''))
        elif fix['action'] == 'fix_permission':
            os.chmod(fix['path'], fix['mode'])
        elif fix['action'] == 'install_dep':
            subprocess.check_call([sys.executable, '-m', 'pip', 'install', fix['package']])
        self.logger.info('Auto‑fix applied: %s', fix)

    def notify_human(self, error, root_cause):
        payload = {'error': error, 'root_cause': root_cause, 'timestamp': time.time()}
        # send to webhook (pseudo‑code)
        # requests.post(self.report_url, json=payload)
        self.logger.warning('Human notified: %s', payload)

