            err={"type":type(e).__name__,"msg":str(e),"trace":traceback.format_exc()}
            root=match_rule(err)
            if root and root in REPAIR_ACTIONS:
                REPAIR_ACTIONS[root]()
            notify_human(generate_introspection_report(err,root))
